-- ============================================
-- LUMA — Enrichissement Thématique 3 (Entretien d'embauche) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"hr": "Recrutement RH", "manager": "Manager technique", "director": "Directrice"}, "start_node": "n1", "nodes": {"n1": {"speaker": "hr", "text": "Let''s start with a quick screening call. Why this company?", "text_fr": "Commençons par un appel de présélection. Pourquoi cette entreprise ?", "choices": [{"text": "I admire your recent innovation in sustainable products.", "next": "n2"}, {"text": "I saw the job posting and it looked interesting.", "next": "n2b"}, {"text": "A former colleague recommended I apply here.", "next": "n2c"}]}, "n2": {"speaker": "hr", "text": "Great, you''re moving on to the technical round.", "text_fr": "Parfait, vous passez au tour technique.", "choices": [{"text": "Looking forward to it.", "next": "n3"}]}, "n2b": {"speaker": "hr", "text": "Okay, let''s continue to the next round.", "text_fr": "D''accord, passons au tour suivant.", "choices": [{"text": "Sounds good.", "next": "n3"}]}, "n2c": {"speaker": "hr", "text": "That''s great to hear, referrals speak volumes about culture fit.", "text_fr": "C''est très bien, les recommandations en disent long sur l''adéquation avec la culture.", "choices": [{"text": "I hope to live up to that.", "next": "n3"}]}, "n3": {"speaker": "manager", "text": "Let''s talk technical skills. How would you handle a tight deadline conflict?", "text_fr": "Parlons compétences techniques. Comment géreriez-vous un conflit de délais serrés ?", "choices": [{"text": "I''d prioritize tasks by impact and communicate early with stakeholders.", "next": "n4"}, {"text": "I''d just work overtime until it''s done.", "next": "n4b"}]}, "n4": {"speaker": "manager", "text": "Good strategic thinking. Here''s a harder one — what if a stakeholder disagrees with your priorities?", "text_fr": "Bonne réflexion stratégique. En voici une plus difficile — que faire si un décideur n''est pas d''accord avec vos priorités ?", "choices": [{"text": "I''d walk them through my reasoning and stay open to their perspective.", "next": "n5"}, {"text": "I''d defer to their seniority, they usually know better.", "next": "n5b"}]}, "n4b": {"speaker": "manager", "text": "I see, though sustainable pacing matters too. Let''s continue.", "text_fr": "Je vois, mais un rythme durable compte aussi. Continuons.", "choices": [{"text": "That''s fair, noted.", "next": "n5"}]}, "n5": {"speaker": "manager", "text": "I appreciate that balance of confidence and openness. Let''s move to the final round with our director.", "text_fr": "J''apprécie cet équilibre entre confiance et ouverture. Passons au tour final avec notre directrice.", "choices": [{"text": "Great, thank you.", "next": "n6"}]}, "n5b": {"speaker": "manager", "text": "Hmm, I''d actually encourage more pushback when you have data to support your view.", "text_fr": "Hmm, je vous encouragerais à plus défendre votre position quand vous avez des données pour l''appuyer.", "choices": [{"text": "That''s useful feedback, I''ll keep that in mind.", "next": "n6"}]}, "n6": {"speaker": "director", "text": "Final question: where do you see yourself in five years?", "text_fr": "Dernière question : où vous voyez-vous dans cinq ans ?", "choices": [{"text": "Growing into a leadership role while deepening my expertise here.", "next": "n7"}, {"text": "Honestly, I''m not sure yet.", "next": "n7b"}]}, "n7": {"speaker": "director", "text": "That aligns really well with our growth plans. One last thing — any concerns about the role?", "text_fr": "Ça correspond vraiment bien à nos plans de croissance. Une dernière chose — des inquiétudes sur le poste ?", "choices": [{"text": "None at all, I''m genuinely excited about it.", "next": "end_offer"}, {"text": "Just curious about the team''s current workload balance.", "next": "end_thoughtful"}]}, "n7b": {"speaker": "director", "text": "That''s honest. We''ll let you know our decision soon.", "text_fr": "C''est honnête. On vous fera savoir notre décision bientôt.", "choices": [{"text": "Thank you for your time today.", "next": "end_neutral"}]}, "end_offer": {"speaker": "director", "text": "We''ll be in touch soon with an offer!", "text_fr": "On vous recontacte bientôt avec une offre !", "end": true, "ending_label": "Parcours réussi, offre en vue 🎉"}, "end_thoughtful": {"speaker": "director", "text": "Good question — shows you''re thinking long-term. We''ll follow up soon.", "text_fr": "Bonne question — ça montre que vous pensez à long terme. On vous recontacte bientôt.", "end": true, "ending_label": "Question pertinente, bonne impression 🎯"}, "end_neutral": {"speaker": "director", "text": "We''ll be in touch with our decision.", "text_fr": "On vous fera part de notre décision.", "end": true, "ending_label": "Parcours complété, résultat incertain 🤞"}}}'::jsonb, is_playable = true
where title = 'Un parcours d''entretien à plusieurs étapes'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"recruiter": "le recruteur", "competitor": "un autre candidat"}, "start_node": "n1", "nodes": {"n1": {"speaker": "recruiter", "text": "For this group exercise, discuss as a team how to solve this business case.", "text_fr": "Pour cet exercice de groupe, discutez en équipe pour résoudre ce cas pratique.", "choices": [{"text": "I''ll suggest we start by clarifying the objective together.", "next": "n2"}, {"text": "(stay quiet and let others lead)", "next": "n2b"}, {"text": "I''ll jump straight into proposing my own solution.", "next": "n2c"}]}, "n2": {"speaker": "competitor", "text": "Good idea, I think we should focus on cost reduction first.", "text_fr": "Bonne idée, je pense qu''on devrait d''abord se concentrer sur la réduction des coûts.", "choices": [{"text": "That''s valid, though I''d also weigh customer impact before deciding.", "next": "n3"}, {"text": "I disagree, we should focus on revenue growth instead.", "next": "n3b"}]}, "n2b": {"speaker": "recruiter", "text": "I noticed you were quiet — what are your thoughts?", "text_fr": "J''ai remarqué que vous étiez silencieux — qu''en pensez-vous ?", "choices": [{"text": "I was actually listening carefully — I think we should balance cost and customer impact.", "next": "n3"}]}, "n2c": {"speaker": "competitor", "text": "That''s one approach, but shouldn''t we hear everyone''s ideas first?", "text_fr": "C''est une approche, mais ne devrait-on pas d''abord entendre les idées de tout le monde ?", "choices": [{"text": "You''re right, my apologies — please share your thoughts.", "next": "n3"}]}, "n3": {"speaker": "recruiter", "text": "Good collaborative thinking there. Now, time''s running short — how do you conclude?", "text_fr": "Belle réflexion collaborative. Le temps presse maintenant — comment conclure ?", "choices": [{"text": "Let''s combine both perspectives into one balanced recommendation.", "next": "n4"}, {"text": "I think we should just vote on the strongest single idea.", "next": "n4b"}]}, "n3b": {"speaker": "competitor", "text": "Interesting, let''s hear both sides then.", "text_fr": "Intéressant, écoutons les deux points de vue alors.", "choices": [{"text": "Agreed, let''s combine both perspectives into a balanced plan.", "next": "n4"}]}, "n4": {"speaker": "recruiter", "text": "That''s a mature way to wrap up a group discussion.", "text_fr": "C''est une façon mature de conclure une discussion de groupe.", "choices": [{"text": "Thank you, teamwork matters a lot to me.", "next": "end_collaborative"}]}, "n4b": {"speaker": "recruiter", "text": "Efficient, though sometimes synthesis beats a quick vote.", "text_fr": "Efficace, même si parfois la synthèse vaut mieux qu''un vote rapide.", "choices": [{"text": "Fair point, I''ll keep that in mind for next time.", "next": "end_efficient"}]}, "end_collaborative": {"speaker": "recruiter", "text": "You stood out for your collaborative approach today.", "text_fr": "Vous vous êtes démarqué par votre approche collaborative aujourd''hui.", "end": true, "ending_label": "Vous vous démarquez du groupe ⭐"}, "end_efficient": {"speaker": "recruiter", "text": "You showed good instincts under time pressure — noted.", "text_fr": "Vous avez montré un bon instinct sous pression — c''est noté.", "end": true, "ending_label": "Efficacité remarquée ⏱️"}}}'::jsonb, is_playable = true
where title = 'Un entretien collectif face à des concurrents'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"director": "la directrice RH"}, "start_node": "n1", "nodes": {"n1": {"speaker": "director", "text": "We''re impressed and would like to make you an offer of $52,000.", "text_fr": "Nous sommes impressionnés et aimerions vous faire une offre de 52 000$.", "choices": [{"text": "Thank you! I actually have another offer at $58,000 — is there room to match that?", "next": "n2"}, {"text": "That''s wonderful, I accept!", "next": "end_accept"}, {"text": "Could you also tell me more about growth opportunities before I decide?", "next": "n2c"}]}, "n2": {"speaker": "director", "text": "I see. Let me check with leadership — can you give us a day?", "text_fr": "Je vois. Laissez-moi vérifier avec la direction — vous pouvez nous laisser une journée ?", "choices": [{"text": "Of course, take your time.", "next": "n3"}]}, "n2c": {"speaker": "director", "text": "Great question. We have a clear promotion path within 18 months for strong performers.", "text_fr": "Excellente question. On a un vrai parcours de promotion sous 18 mois pour les bons éléments.", "choices": [{"text": "That''s reassuring. I do have a competing offer at $58,000, though.", "next": "n2"}]}, "n3": {"speaker": "director", "text": "Good news — we can offer $57,000 plus additional benefits. Does that work?", "text_fr": "Bonne nouvelle — on peut proposer 57 000$ plus des avantages supplémentaires. Ça vous convient ?", "choices": [{"text": "That''s excellent, I''m happy to accept!", "next": "end_countered"}, {"text": "Very close — could we settle at $58,000 to match exactly?", "next": "n4"}]}, "n4": {"speaker": "director", "text": "(pauses) You really don''t back down easily, do you?", "text_fr": "(marque une pause) Vous ne lâchez vraiment pas facilement, hein ?", "choices": [{"text": "I believe in knowing my worth, respectfully.", "next": "end_pushed"}, {"text": "Fair enough, $57,000 works great for me actually.", "next": "end_settled"}]}, "end_accept": {"speaker": "director", "text": "Fantastic, welcome aboard!", "text_fr": "Fantastique, bienvenue à bord !", "end": true, "ending_label": "Offre acceptée directement 🤝"}, "end_countered": {"speaker": "director", "text": "Perfect, we''re thrilled to have you.", "text_fr": "Parfait, on est ravis de vous accueillir.", "end": true, "ending_label": "Contre-offre bien négociée 💰"}, "end_pushed": {"speaker": "director", "text": "Respect that. Deal, $58,000 it is!", "text_fr": "Je respecte ça. Marché conclu, va pour 58 000$ !", "end": true, "ending_label": "Négociation maximale réussie 🏆"}, "end_settled": {"speaker": "director", "text": "Glad we found common ground — welcome to the team!", "text_fr": "Content qu''on ait trouvé un terrain d''entente — bienvenue dans l''équipe !", "end": true, "ending_label": "Accord satisfaisant trouvé 🤝"}}}'::jsonb, is_playable = true
where title = 'Un entretien qui se termine par une contre-offre'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
